a=read('associations.csv');s=read('model_scores_ranks.csv');t=read('truths_quantiles_floors.csv');v=read('production_validation.csv');c=read('coverage_summary.csv');conv=read('score_convergence.csv');qc=read('convergence.csv');success=json.loads((R/'SUCCESS.json').read_text());prod=json.loads((O/'SUCCESS.json').read_text());audit=json.loads((R/'forecast_audit.json').read_text());roster=json.loads((R/'roster.json').read_text())
planhash=(O/'PLAN.sha256').read_text().strip();parts=[]
parts.append('# Starsim fixed-state production and retrospective rescore\n\n**Completed: 16,000 branches, 4,000 independent continuation sets, 1,000 per world, four paired arms per set.** All production and rescore validation passed. Original forecasts, prior audit/failure artifacts and manuscript inputs were preserved. No model calls, cloud spending or remote writes were used. This is a retrospective fixed-hidden-state rescore, not a newly elicited benchmark and not the distribution conditional only on the displayed report.\n')
parts.append('## Main numerical changes\n\nScores below are normalized excess five-quantile CRPS approximations (lower is better). The paper constants remain **C40=200 and C60=300 people**. Panel membership is complete-item based, exactly as in the paper; planned repetition completeness is audited separately. Every before/after comparison uses the same models and forecasts.\n')
rows=[]
for group in ['cont_uncond','cont_int_c25','cont_int_c50','cont_int_c90','interventional_pooled','all_continuous']:
 rs=[r for r in s if r['group']==group and r['horizon']=='pooled'];rows.append([group,len(rs),fmt(np.mean([f(r['old_excess']) for r in rs])),fmt(np.mean([f(r['new_excess']) for r in rs])),fmt(np.mean([f(r['delta']) for r in rs])),fmt(max(abs(f(r['rank_move'])) for r in rs),1)])
